#include <stdio.h>
int main()
{
    int n, i, flag = 0;
    scanf("%d", &n);
    for (i = 2; i < n; i++) {
        if (n % i == 0) {
            flag = 1;
            break;
        }
    }
    if (flag == 0)
        printf("Prime");
    else
        printf("Not Prime");
    return 0;
}

int largest(int arr[], int n)
{
    int i, max;
    max = arr[0];
    for (i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}
